(function(){
  function patch(o){
    if(!o||typeof o!=='object')return;
    if(Array.isArray(o)){for(var i=0;i<o.length;i++)patch(o[i]);return;}
    if(typeof o.en==='string'&&!o.vi&&PRELEARN_VI[o.en])o.vi=PRELEARN_VI[o.en];
    for(var k in o){if(o.hasOwnProperty(k)&&typeof o[k]==='object')patch(o[k]);}
  }
  ['PRELEARN_CHAPTERS_SMTV', 'PRELEARN_CHAPTERS_NBGA', 'PRELEARN_QUIZ_SMTV', 'PRELEARN_QUIZ_NBGA'].forEach(function(n){
    try{patch(window[n]);}catch(e){}
  });
})();
